const err = $input.first().json;
const wfName = (err.workflow?.name || '').trim();
// Anti-recursion: only skip errors originating from this handler workflow itself
if (/^Arcadia - Central Error Handler$/i.test(wfName)) {
  return [];
}
return [{ json: err }];

const err = $input.first().json;
const execution = err.execution || {};
const workflow = err.workflow || {};
const node = err.trigger?.error?.node || {};
const message = err.trigger?.error?.message || 'unknown error';
const severity = message.match(/critical|payment|refund/i) ? 'critical' : 'error';

return [{
  json: {
    workflow_name: workflow.name || 'unknown',
    workflow_id: String(workflow.id || ''),
    execution_id: String(execution.id || ''),
    node_name: node.name || err.trigger?.error?.node?.name || null,
    agent_name: workflow.name?.includes('Laila') ? 'sales' : (workflow.name?.includes('Follow') ? 'cs' : 'system'),
    source_channel: $json.source_channel || null,
    lead_id: $json.lead_id || null,
    booking_id: $json.booking_id || null,
    severity,
    error_message: message.slice(0, 2000),
    payload: {
      execution_url: execution.url,
      last_node: execution.lastNodeExecuted,
      mode: execution.mode
    },
    retry_count: 0,
    status: 'open'
  }
}];

